    if n < 0:
        return 0
    elif n == 0:
        return 1
    else:
        dp = [0]*(n+1)
        dp[0] = dp[1] = 1
        dp[2] = 2
        for i in range(3, n+1):
            dp[i] = dp[i-1] + dp[i-2] + dp[i-3]
        return dp[n]
```

