def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return '0'
    res = ''
    while n != 0:
        r = n % 3
        n //= 3
        if r == 2:
            res = '-' + res
            n += 1
        elif r == 1:
            res = '+' + res
        else:
            res = '0' + res
    return res.lstrip('0')
```

