def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    def is_attack(i, j):
        for k in range(0, n):
            if board[k][j] == 1 or board[i][k] == 1:
                return True
        for k in range(0, n):
            for l in range(0, n):
                if (k + l == i + j) or (k - l == i - j):
                    if board[k][l] == 1:
                        return True
        return False

    def N_Queens(n, blocked):
        if n == 0:
            return 1
        count = 0
        for i in range(0, n):
            for j in range(0, n):
                if (i, j) not in blocked:
                    board[i][j] = 1
                    if not is_attack(i, j):
                        count += N_Queens(n - 1, blocked)
                    board[i][j] = 0
        return count

    board = [[0]*n for _ in range(n)]
    for block in blocked:
        board[block[0]][block[1]] = -1
    return N_Queens(n, blocked)
