from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    visited = [[0]*cols for _ in range(rows)]
    directions = [(0,1), (0,-1), (1,0), (-1,0)]

    def bfs(x, y, z):
        q = deque([(x, y, z)])
        visited[x][y] = 1
        while q:
            x, y, z = q.popleft()
            if grid[x][y] == 'E':
                return visited[x][y] - 1
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < cols and visited[nx][ny] == 0 and grid[nx][ny] != '#':
                    if z == 0 and grid[nx][ny] == 'E':
                        continue
                    q.append((nx, ny, z))
                    visited[nx][ny] = visited[x][y] + 1
                elif 0 <= nx < rows and 0 <= ny < cols and visited[nx][ny] == 0 and grid[nx][ny] == '#' and z == 0:
                    q.append((nx, ny, 1))
                    visited[nx][ny] = visited[x][y] + 1
        return -1

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                return bfs(i, j, 0)
```

This code uses a Breadth-First Search (BFS) algorithm to find the shortest path from the starting point to the ending point in the grid. The BFS algorithm is implemented in the `bfs` function. The `visited` list is used to keep track of the cells that have been visited. The `directions` list is used to move in the four directions (up, down, left, right). The `bfs` function returns the minimum number of moves required to reach the ending point, or `-1` if it is not possible to reach the ending point.

