from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = (-1, -1), (-1, -1)
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)
    if start == (-1, -1) or end == (-1, -1):
        return -1

    moves = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    visited = set()
    queue = deque([(start, 0, False)])
    while queue:
        (x, y), dist, broken = queue.popleft()
        if (x, y) == end:
            return dist
        for dx, dy in moves:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols:
                if grid[nx][ny] == '#' and not broken:
                    queue.append(((nx, ny), dist + 1, True))
                elif grid[nx][ny] == '.' and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append(((nx, ny), dist + 1, broken))
    return -1
```

This function uses a Breadth-First Search (BFS) algorithm to find the shortest path from the start to the end in the grid. It keeps track of the current position, the distance from the start, and whether a wall has been broken. If a wall is encountered and it has not been broken yet, it adds a new state to the queue with the wall broken. If an empty cell is encountered and it has not been visited yet, it adds a new state to the queue without breaking a wall. If the end is reached, it returns the distance. If no path is found, it returns -1.

