def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []
    graph = [[] for _ in range(n)]
    indegree = [0] * n
    for a, b in pairs:
        if a == b:
            return []
        graph[a].append(b)
        indegree[b] += 1
    for i in range(n):
        if indegree[i] == 0:
            indegree[i] = float('inf')
    queue = [i for i in range(n) if indegree[i] == float('inf')]
    order = []
    while queue:
        u = min(queue)
        queue.remove(u)
        order.append(u)
        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)
    return order if len(order) == n else []
```

