def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return 0, 1

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    x, m = 0, 1
    for r, m_new in congruences:
        if gcd(m, m_new) != 1:
            return None
        k = m_new // gcd(m, m_new)
        x = (x * k * m_new + r * m) // m_new
        m *= k

