def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []
    bins = [[]]
    for size in sorted(sizes):
        if size > capacity:
            raise ValueError("Item size exceeds capacity")
        for bin in bins:
            if sum(bin) + size <= capacity:
                bin.append(size)
                break
        else:
            bins.append([size])
    return bins
