from heapq import heappop, heappush

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    shortest_paths = {source: 1}
    heap = [(0, source)]
    while heap:
        d, node = heappop(heap)
        if node not in shortest_paths:
            shortest_paths[node] = 0
        for neighbor in graph[node]:
            if neighbor not in shortest_paths or d + 1 < shortest_paths[neighbor]:
                shortest_paths[neighbor] = d + 1
                heappush(heap, (d + 1, neighbor))
    return shortest_paths[target] if target in shortest_paths else 0
