    def matrix_multiply_mod(a: list[list[int]], b: list[list[int]], mod: int) -> list[list[int]]:
        return [[sum(a[i][k]*b[k][j] for k in range(len(a))) % mod for j in range(len(b[0]))] for i in range(len(a))]

    def matrix_power(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
