    if not congruences:
        return (0, 1)

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    r, m = congruences[0]
    for r, m in congruences[1:]:
        r %= m
        if r < 0:
            r += m
