from collections import defaultdict, deque

def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []
    graph = defaultdict(list)
    in_degree = [0]*n
    for a, b in pairs:
        if a == b:
            return []
        graph[a].append(b)
        in_degree[b] += 1
    q = deque([i for i in range(n) if in_degree[i] == 0])
    res = []
    while q:
        node = q.popleft()
        res.append(node)
        for nei in graph[node]:
            in_degree[nei] -= 1
            if in_degree[nei] == 0:
                q.append(nei)
    return res if len(res) == n else []
```

