from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = (0, 0), (0, 0)
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    queue = deque([(start, 0, False)])
    visited = {start: 0}
    while queue:
        (x, y), steps, broken = queue.popleft()
        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols:
                if grid[nx][ny] == '#' and not broken:
                    queue.append(((nx, ny), steps + 1, True))
                    if (nx, ny) not in visited or visited[nx, ny] > steps + 1:
                        visited[nx, ny] = steps + 1
                elif grid[nx][ny] == '.' or (grid[nx][ny] == 'E' and broken):
                    if (nx, ny) not in visited or visited[nx, ny] > steps + 1:
                        visited[nx, ny] = steps + 1
                        queue.append(((nx, ny), steps + 1, broken))

    if end in visited:
        return visited[end]
    else:
        return -1
```

