    if not 2 <= from_base <= 36 or not 2 <= to_base <= 36:
        raise ValueError("Both from_base and to_base must be between 2 and 36")

    if not all(('0' <= char <= '9' or 'a' <= char.lower() <= 'z') for char in number):
