def decode_runs(encoded: str) -> str:
    decoded = ""
    i = 0
    while i < len(encoded):
        if encoded[i] == '\\':
            i += 1
            if i < len(encoded) and encoded[i] in '~0123456789':
                count = int(encoded[i])
                i += 1
            else:
