def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])
    new_grid = [[0]*cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            new_grid[r][c] = grid[r][c]

    while True:
        to_crush = []
        for r in range(rows):
            for c in range(cols):
                if new_grid[r][c] >= 4:
                    to_crush.append((r, c))

        if not to_crush:
            break

        for r, c in to_crush:
            new_grid[r][c] -= 4
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    new_grid[nr][nc] += 1

    return new_grid
