def subsets_with_sum(nums: list[int], k: int) -> list[list[int]]:
    def dfs(nums, target, path, res):
        if sum(path) == target:
            res.append(path)
        if sum(path) > target:
            return
        for i in range(len(nums)):
            dfs(nums[i+1:], target, path+[nums[i]], res)
    nums.sort()
    res = []
    dfs(nums, k, [], res)
    return res
