def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end:
        return []

    busy.sort()
    free = []
    last_end = day_start

    for start, end in busy:
        if start < day_end and end > day_start:
            if start < day_start:
                start = day_start
            if end > day_end:
                end = day_end
            if start < last_end:
                start = last_end
            if start < end:
                free.append((start, end))
            last_end = end

    if last_end < day_end:
        free.append((last_end, day_end))

    return [(start, end) for start, end in free if end - start >= min_len]
