def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not 2 <= from_base <= 36 or not 2 <= to_base <= 36:
        raise ValueError("Bases must be between 2 and 36")

    if not number or number == '-' or any(not '0' <= char <= '9' and not 'a' <= char.lower() <= 'z' for char in number[1:]):
        raise ValueError("Invalid number")

    if number[0] == '-':
        negative = True
        number = number[1:]
    else:
        negative = False

    base10 = 0
    for i, digit in enumerate(reversed(number)):
        if '0' <= digit <= '9':
            base10 += int(digit) * (from_base ** i)
        else:
            base10 += (ord(digit.lower()) - ord('a') + 10) * (from_base ** i)

    if base10 == 0:
        return '0'

    digits = []
    while base10:
        base10, remainder = divmod(base10, to_base)
        if 10 <= remainder <= 35:
            digits.append(chr(remainder - 10 + ord('a')))
        else:
            digits.append(str(remainder))

    if negative:
        return '-' + ''.join(reversed(digits))
    else:
        return ''.join(reversed(digits))
```

