    while queue:
        (cost, node, path) = heapq.heappop(queue)
        if node not in seen:
            seen.add(node)
            if node == goal:
                return (cost, path)
            for (next_node, next_cost) in graph[node].items():
                if next_node not in seen:
                    heapq.heappush(queue, (cost + next_cost, next_node, path + [next_node]))
    return None
```

