from collections import deque

def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    start, end = None, None

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    queue = deque([(*start, 0)])
    visited = {start}

    while queue:
        x, y, steps = queue.popleft()

        if (x, y) == end:
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#' and (nx, ny) not in visited:
                queue.append((nx, ny, steps + 1))
                visited.add((nx, ny))

    return -1
```

This function uses a Breadth-First Search (BFS) algorithm to find the shortest path from the start cell to the end cell. It keeps track of the number of steps taken at each cell and adds the neighboring cells to the queue if they are not a wall and have not been visited before. The function returns the number of steps taken to reach the end cell if it exists, otherwise it returns -1.

