def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Calculate the width of each column
    widths = [max(len(cell) for cell in col) for col in zip(*rows)]

    # Create the formatted table
    table = []
    for row in rows:
        formatted_row = []
        for i, cell in enumerate(row):
            align = aligns[i]
            width = widths[i]
            if align == 'l':
                formatted_row.append(cell.ljust(width))
            elif align == 'r':
                formatted_row.append(cell.rjust(width))
            elif align == 'c':
                formatted_row.append(cell.center(width))
        table.append(" | ".join(formatted_row))

    # Add padding to the end of each line
    max_line_length = max(len(line) for line in table)
    for i, line in enumerate(table):
        table[i] = line + ' ' * (max_line_length - len(line))

    return '\n'.join(table)
```

