import operator
import ast

def matches_filter(expression: str, record: dict) -> bool:
    # Define the operators
    operators = {ast.Add: operator.add, ast.Sub: operator.sub,
                  ast.Mult: operator.mul, ast.Div: operator.truediv,
                  ast.USub: operator.neg, ast.BitXor: operator.xor,
                  ast.FloorDiv: operator.floordiv, ast.Mod: operator.mod,
                  ast.Pow: operator.pow, ast.LShift: operator.lshift,
                  ast.RShift: operator.rshift, ast.And: operator.and_,
                  ast.Or: operator.or_, ast.Lt: operator.lt,
                  ast.Gt: operator.gt, ast.Eq: operator.eq,
                  ast.GtE: operator.ge, ast.LtE: operator.le,
                  ast.Not: operator.not_, ast.Is: operator.is_,
                  ast.IsNot: operator.is_not}

    # Parse the expression
    node = ast.parse(expression, mode='eval').body

    # Check if all variables are in the record
    for var in [n.id for n in ast.walk(node) if isinstance(n, ast.Name)]:
        if var not in record:
            raise ValueError(f"Variable {var} not found in record")

    # Evaluate the expression
    def evaluate(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.Str):
            return node.s
        elif isinstance(node, ast.Name):
            return record[node.id]
        elif isinstance(node, ast.BinOp):
            return operators[type(node.op)](evaluate(node.left), evaluate(node.right))
        elif isinstance(node, ast.UnaryOp):
            return operators[type(node.op)](evaluate(node.operand))
        elif isinstance(node, ast.Compare):
            left = evaluate(node.left)
            return [operators[type(op)](left, evaluate(com)) for com in node.comparators]
        elif isinstance(node, ast.BoolOp):
            return operators[type(node.op)](*[evaluate(val) for val in node.values])
        else:
            raise ValueError(f"Unsupported node type {type(node)}")

    return evaluate(node)
```

