def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Calculate the width of each column
    widths = [max(len(row[i]) for row in rows) for i in range(len(rows[0]))]

    # Create the formatted table
    table = []
    for row in rows:
        formatted_row = []
        for i, cell in enumerate(row):
            align = aligns[i]
            width = widths[i]
            if align == 'l':
                formatted_row.append(cell.ljust(width))
            elif align == 'r':
                formatted_row.append(cell.rjust(width))
            elif align == 'c':
                formatted_row.append(cell.center(width))
        table.append(" | ".join(formatted_row))

