    final_balances = balances.copy()
    for i, op in enumerate(ops):
        op_type, account, *args = op
        if op_type not in ['deposit', 'withdraw', 'transfer', 'freeze', 'unfreeze']:
            failed.append(i)
            continue
        if account not in final_balances:
            failed.append(i)
            continue
        if op_type == 'freeze' and account not in frozen:
            frozen[account] = True
