        if op_type == 'deposit':
            amount = args[0]
            if amount <= 0:
                failed.append(i)
                continue
            final_balances[account] += amount
        elif op_type == 'withdraw':
            amount = args[0]
            if amount <= 0 or final_balances[account] - amount < 0:
                failed.append(i)
                continue
            final_balances[account] -= amount
        elif op_type == 'transfer':
            target, amount = args
            fee = 2
            if amount <= 0 or amount + fee > final_balances[account] or account == target or target not in final_balances:
                failed.append(i)
                continue
            final_balances[account] -= amount + fee
            final_balances[target] = final_balances[target] + amount
    return (final_balances, failed)
