def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    pointer = 0
    for i in range(1000):
        if pointer >= len(program):
            return stack
        instruction = program[pointer].split()
        if instruction[0] == 'PUSH':
            stack.append(int(instruction[1]))
        elif instruction[0] == 'POP':
            if not stack:
                return None
            stack.pop()
        elif instruction[0] == 'DUP':
            if not stack:
                return None
            stack.append(stack[-1])
        elif instruction[0] == 'SWAP':
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction[0] == 'ADD':
            if len(stack) < 2:
                return None
            stack[-2] = stack[-2] + stack[-1]
            stack.pop()
        elif instruction[0] == 'SUB':
            if len(stack) < 2:
                return None
            stack[-2] = stack[-2] - stack[-1]
            stack.pop()
        elif instruction[0] == 'MUL':
            if len(stack) < 2:
                return None
            stack[-2] = stack[-2] * stack[-1]
            stack.pop()
        elif instruction[0] == 'JMP':
            pointer = int(instruction[1]) - 1
        elif instruction[0] == 'JZ':
            if not stack:
                return None
            if stack[-1] == 0:
                pointer = int(instruction[1]) - 1
            stack.pop()
        pointer += 1
    return stack
```

