def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []
    waiting_orders = {}

    for event in events:
        kind, item, quantity = event

        if kind == 'receive':
            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity

            # Send waiting orders
            while waiting_orders.get(item, 0) >= quantity:
                waiting_orders[item] -= quantity
                quantity = 0
                break

            if quantity > 0:
                waiting_orders[item] = quantity

        elif kind == 'order':
            if item in stock and stock[item] >= quantity:
                stock[item] -= quantity

            elif item not in stock or stock[item] < quantity:
                waiting.append((item, quantity))

    # Add remaining stock to the final stock dictionary
    for item, quantity in stock.items():
        if item in waiting_orders:
            waiting_orders[item] += quantity
        else:
            waiting_orders[item] = quantity

    stock.update(waiting_orders)

    return stock, sorted(waiting, key=lambda x: events.index(('order', x[0], x[1])))
