def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    frozen = {}
    failed = []
    final_balances = balances.copy()

    for i, op in enumerate(ops):
        op_type, *args = op

        if op_type == 'deposit':
            account, amount = args
            if account in frozen:
                failed.append(i)
            elif amount > 0:
                final_balances[account] = final_balances.get(account, 0) + amount
            else:
                failed.append(i)

        elif op_type == 'withdraw':
            account, amount = args
            if account in frozen:
                failed.append(i)
            elif account in final_balances and final_balances[account] - amount - 2 >= 0:
                final_balances[account] -= (amount + 2)
            else:
                failed.append(i)

        elif op_type == 'transfer':
            source, target, amount = args
            if source in frozen or target in frozen or amount <= 0 or source not in final_balances or final_balances[source] - amount - 2 < 0:
                failed.append(i)
            else:
                final_balances[source] -= (amount + 2)
                final_balances[target] = final_balances.get(target, 0) + amount

        elif op_type == 'freeze':
            account = args[0]
            if account in frozen or account not in final_balances:
                failed.append(i)
            else:
                frozen[account] = True

        elif op_type == 'unfreeze':
            account = args[0]
            if account not in frozen:
                failed.append(i)
            else:
                del frozen[account]

        else:
            failed.append(i)

    return (final_balances, failed)
```

This code first initializes an empty dictionary `frozen` to keep track of frozen accounts and an empty list `failed` to store the indices of failed operations. It then iterates over the operations in the order they are given. For each operation, it checks the type of operation and performs the corresponding action. If an operation fails, its index is added to the `failed` list. Finally, it returns a tuple containing the final balances and the list of failed operation indices.

```python
def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    frozen = {}
    failed = []
    final_balances = balances.copy()

    for i, op in enumerate(ops):
        operation, account, amount = op

        if (account not in final_balances or
            amount <= 0 or
            account in frozen or
            operation not in ['deposit', 'withdraw', 'transfer', 'freeze', 'unfreeze'] or
            (operation == 'withdraw' and final_balances[account] - amount < 0) or
            (operation == 'transfer' and ops[i][2] == ops[i][1]) or
            (operation == 'transfer' and final_balances[ops[i][1]] - amount - 2 < 0)):
            failed.append(i)
            continue

        if operation == 'deposit':
            final_balances[account] += amount
        elif operation == 'withdraw':
            final_balances[account] -= amount
        elif operation == 'transfer':
            final_balances[account] -= amount + 2
            final_balances[ops[i][2]] = final_balances[ops[i][2]] + amount

        if operation == 'freeze':
            frozen[account] = True
        elif operation == 'unfreeze':
            if account in frozen:
                del frozen[account]

    return (final_balances, failed)
